-- JobTot fictional demo seed. Apply EF migrations first.
-- Demo-only password: JobTotDemo2026! (ASP.NET Identity PBKDF2 hashes).
-- Select the intended database in SSMS, or use sqlcmd -d. No schema/database creation.
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() IN (N'master', N'model', N'msdb', N'tempdb') THROW 51000, 'Select your JobTot demo database first.', 1;
IF OBJECT_ID(N'dbo.CandidateJobSubmissions', N'U') IS NULL OR OBJECT_ID(N'dbo.ChatMessages', N'U') IS NULL THROW 51001, 'Apply current EF migrations before seeding.', 1;
DECLARE @Now datetimeoffset = TODATETIMEOFFSET(SYSUTCDATETIME(), '+00:00');
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @LockResult int;
EXEC @LockResult = sp_getapplock @Resource=N'JobTot.SqlDemoSeed.v1', @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=10000;
IF @LockResult < 0 THROW 51002, 'Could not acquire seed lock.', 1;

