UPDATE m SET Url=p.NewUrl FROM dbo.Media m JOIN @Paths p ON m.Url=p.OldUrl;
DECLARE @Old nvarchar(2048), @New nvarchar(2048);
DECLARE paths CURSOR LOCAL FAST_FORWARD FOR SELECT OldUrl,NewUrl FROM @Paths;
OPEN paths; FETCH NEXT FROM paths INTO @Old,@New;
WHILE @@FETCH_STATUS=0
BEGIN
 UPDATE dbo.Companies SET Culture=REPLACE(Culture,@Old,@New) WHERE Culture LIKE N'%'+@Old+N'%';
 FETCH NEXT FROM paths INTO @Old,@New;
END;
CLOSE paths; DEALLOCATE paths;


